const recipes = Object.fromEntries(entries.map(([id, nameAr, nameEn, nameFr, nameEs, nameDe, category, mealType, protein, carbs, fat, cooking, region]) => [id, {
  id: `ee-${id}`,
  nameAr,
  nameEn,
  nameFr,
  nameEs,
  nameDe,
  category,
  mealType,
  grams: 100,
  kcal: Math.round(4 * protein + 4 * carbs + 9 * fat),
  protein,
  carbs,
  fat,
  cooking,
  region,
  diaspora_priority: ['eastern_european', 'slavic', 'high_protein'],
}]));

export const RECIPE_IDS = entries.map(([id]) => id);

export function buildRows(ids) {
  return ids.map((id) => {
    const row = recipes[id];
    if (!row) throw new Error(`Unknown Eastern European recipe profile: ${id}`);
    return { ...row };
  });
}
